//! SSR parity of the native `TyThemePalette`. The element is
//! `kind: "self-rendering"` with `examples: []` in its definition — the
//! composed grid is runtime data no renderer can express up front — so,
//! like the toast and command-palette ports, there are no fixtures and the
//! tests assert the exact SSR string of the states SSR can represent: the
//! bare host (closed) and the fully composed dialog (open).

use dioxus::prelude::*;
use tympan_dioxus::elements;

use super::common;

#[test]
fn closed() {
    fn app() -> Element {
        rsx! { elements::TyThemePalette { instance: "i" } }
    }
    assert_eq!(common::render(app), CLOSED);
}

#[test]
fn open() {
    fn app() -> Element {
        rsx! { elements::TyThemePalette { instance: "i", open: true } }
    }
    assert_eq!(common::render(app), OPEN);
}

